<?php

declare(strict_types=1);

namespace FastWebsite\Validation;

use FastWebsite\Repositories\ProjectRepository;

final class ProjectValidator
{
    private const STATUSES=['planned','ongoing','completed','suspended','cancelled'];
    public function __construct(private readonly ProjectRepository$projects){}
    /** @param array<string,string|null> $input @return array{data:array<string,mixed>,lead_unit_id:?int,errors:list<string>} */ public function validate(array$input,?int$existingId=null):array{$errors=[];$title=trim((string)($input['title']??''));$slug=strtolower(trim((string)($input['slug']??'')));if($slug==='')$slug=$this->slugify($title);$department=$this->id($input['lead_department_id']??null);$unit=$this->id($input['lead_research_unit_id']??null);$media=$this->id($input['hero_media_id']??null);if($title===''||mb_strlen($title)>300)$errors[]='Project title is required and must be 300 characters or fewer.';if($slug===''||mb_strlen($slug)>320||preg_match('/^[a-z0-9]+(?:-[a-z0-9]+)*$/',$slug)!==1)$errors[]='Slug must contain lowercase letters, numbers, and single hyphens only.';elseif($this->projects->slugExists($slug,$existingId))$errors[]='That project slug is already in use.';if($department===null||!$this->projects->relationExists('departments',$department))$errors[]='Select a valid lead department.';if(trim((string)($input['lead_research_unit_id']??''))!==''&&($unit===null||!$this->projects->relationExists('research_units',$unit)))$errors[]='Select a valid lead research unit.';if(trim((string)($input['hero_media_id']??''))!==''&&($media===null||!$this->projects->relationExists('media',$media)))$errors[]='Select an active image.';$projectStatus=(string)($input['project_status']??'planned');if(!in_array($projectStatus,self::STATUSES,true))$errors[]='Choose a valid project status.';$start=$this->date($input['start_date']??null,'Start date',$errors);$end=$this->date($input['end_date']??null,'End date',$errors);if($start!==null&&$end!==null&&$end<$start)$errors[]='End date cannot be before the start date.';$budget=trim((string)($input['budget_amount']??''));if($budget!==''&&(!is_numeric($budget)||(float)$budget<0))$errors[]='Budget must be zero or a positive number.';$currency=strtoupper(trim((string)($input['currency_code']??'')));if($currency!==''&&preg_match('/^[A-Z]{3}$/',$currency)!==1)$errors[]='Currency must use a three-letter code such as UGX or USD.';$projectUrl=$this->nullable($input['project_url']??null);if($projectUrl!==null&&filter_var($projectUrl,FILTER_VALIDATE_URL)===false)$errors[]='Enter a valid project URL.';$text=[];foreach(['summary','objectives','methodology','expected_outputs','outcomes','impact']as$field){$text[$field]=$this->nullable($input[$field]??null);if($text[$field]!==null&&mb_strlen($text[$field])>100000)$errors[]=ucfirst(str_replace('_',' ',$field)).' is too long.';}return['data'=>['lead_department_id'=>$department,'title'=>$title,'short_title'=>$this->limited($input['short_title']??null,120,'Short title',$errors),'slug'=>$slug,...$text,'project_status'=>$projectStatus,'start_date'=>$start,'end_date'=>$end,'budget_amount'=>$budget!==''?number_format((float)$budget,2,'.',''):null,'currency_code'=>$currency!==''?$currency:null,'funding_reference'=>$this->limited($input['funding_reference']??null,150,'Funding reference',$errors),'project_url'=>$projectUrl,'hero_media_id'=>$media],'lead_unit_id'=>$unit,'errors'=>$errors];}
    /** @param list<string> $errors */ private function date(?string$value,string$label,array&$errors):?string{$v=trim((string)$value);if($v==='')return null;if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$v)!==1||strtotime($v)===false){$errors[]=$label.' must use YYYY-MM-DD.';return null;}return$v;}
    /** @param list<string> $errors */ private function limited(?string$value,int$max,string$label,array&$errors):?string{$v=$this->nullable($value);if($v!==null&&mb_strlen($v)>$max)$errors[]="$label must be $max characters or fewer.";return$v;}
    private function nullable(?string$value):?string{$v=trim((string)$value);return$v===''?null:$v;}private function id(?string$value):?int{if($value===null||trim($value)==='')return null;$v=filter_var($value,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);return$v===false?null:(int)$v;}private function slugify(string$value):string{$ascii=iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$value);return trim(strtolower((string)preg_replace('/[^a-zA-Z0-9]+/','-',$ascii===false?$value:$ascii)),'-');}
}
